function sessionDiagEmit(attempt,fields){if(typeof sessionDiag==="function")sessionDiag(attempt,fields)}
async function waitForWalletProvider(source,ms=4000,attempt=null){const providerAttempt=attempt|| (typeof sessionDiagAttempt==="function"?sessionDiagAttempt(CURRENT_NETWORK):{count:0});sessionDiag(providerAttempt,{stage:"provider_wait",network:CURRENT_NETWORK,provider:source,ok:true,reason:"available"});let p;const deadline=Date.now()+ms;while(!(p=walletProvider(source))&&Date.now()<deadline)await new Promise(resolve=>setTimeout(resolve,75));sessionDiag(providerAttempt,{stage:"provider_detection",network:CURRENT_NETWORK,provider:source,ok:Boolean(p),reason:p?"available":"provider-timeout"});return p}
