async function consumeHandoff(){const attempt=sessionDiagAttempt(CURRENT_NETWORK);let handoff,raw=null;try{raw=sessionStorage.getItem("kelvara_handoff");sessionDiag(attempt,{stage:"handoff_load",network:CURRENT_NETWORK,ok:true,reason:raw?"present":"missing"});try{handoff=JSON.parse(raw||"null");sessionDiag(attempt,{stage:"handoff_parse",network:CURRENT_NETWORK,ok:true,reason:"parsed"})}catch(error){sessionDiag(attempt,{stage:"handoff_parse",network:CURRENT_NETWORK,ok:false,reason:"malformed",errorClass:sessionDiagErrorClass(error)})}}catch(error){sessionDiag(attempt,{stage:"handoff_load",network:CURRENT_NETWORK,ok:false,reason:"storage-read-failed",errorClass:sessionDiagErrorClass(error)})}const networkValid=validNetworkRecord(handoff),schemaValid=Boolean(typeof handoff?.wallet==="string"&&handoff.wallet.length>0&&handoff.wallet.length<=64&&WALLET_SOURCES.includes(handoff.source)&&typeof handoff.genesisHash==="string"&&handoff.genesisHash.length>0&&typeof handoff.token==="string"&&handoff.token.length>0&&handoff.token.length<=4096&&handoff.evidence&&typeof handoff.evidence==="object");sessionDiag(attempt,{stage:"handoff_schema",network:CURRENT_NETWORK,provider:handoff?.source,ok:schemaValid,reason:schemaValid?"valid":"invalid"});sessionDiag(attempt,{stage:"network_genesis_validation",network:CURRENT_NETWORK,provider:handoff?.source,ok:networkValid,reason:networkValid?"valid":"invalid-genesis"});if(!networkValid||!schemaValid){try{sessionStorage.removeItem("kelvara_handoff")}catch(error){sessionDiag(attempt,{stage:"handoff_cleanup",network:CURRENT_NETWORK,ok:false,reason:"storage-write-failed",errorClass:sessionDiagErrorClass(error)})}sessionDiag(attempt,{stage:"consume_final",network:CURRENT_NETWORK,provider:handoff?.source,ok:false,reason:"handoff-failed"});return false}try{const p=await waitForWalletProvider(handoff.source,4000,attempt),current=await connectTrustedWallet(p,handoff.wallet,attempt);if(!current||current!==handoff.wallet||p.isConnected===false)throw new Error("trusted_wallet_mismatch");walletAddress=handoff.wallet;walletSource=handoff.source;activeProvider=p;protectionToken=handoff.token;verifiedGenesisHash=handoff.genesisHash;evidence=handoff.evidence;try{saveAppSession(walletAddress,walletSource,protectionToken);sessionDiag(attempt,{stage:"app_session_save",network:CURRENT_NETWORK,provider:handoff.source,ok:true,reason:"saved"});sessionDiag(attempt,{stage:"session_saved",network:CURRENT_NETWORK,provider:handoff.source,ok:true,reason:"session-saved"})}catch(error){sessionDiag(attempt,{stage:"app_session_save",network:CURRENT_NETWORK,provider:handoff.source,ok:false,reason:error?.message==="invalid_app_session"?"invalid":"storage-write-failed",errorClass:sessionDiagErrorClass(error)});throw error}try{bindWalletEvents(p);rememberWallet(walletAddress,walletSource);renderPosition(evidence);if(evidence.position)renderAuthority(evidence);document.querySelector("main").classList.remove("product-pending")}catch(error){sessionDiag(attempt,{stage:"destination_finalize",network:CURRENT_NETWORK,provider:handoff.source,ok:false,reason:"destination-finalize-failed",errorClass:sessionDiagErrorClass(error)});throw error}try{sessionStorage.removeItem("kelvara_handoff")}catch(error){sessionDiag(attempt,{stage:"handoff_cleanup",network:CURRENT_NETWORK,provider:handoff.source,ok:false,reason:"storage-write-failed",errorClass:sessionDiagErrorClass(error)});throw error}sessionDiag(attempt,{stage:"consume_final",network:CURRENT_NETWORK,provider:handoff.source,ok:true,reason:"session-saved"});return true}catch(error){try{sessionStorage.removeItem("kelvara_handoff")}catch(cleanupError){sessionDiag(attempt,{stage:"handoff_cleanup",network:CURRENT_NETWORK,ok:false,reason:"storage-write-failed",errorClass:sessionDiagErrorClass(cleanupError)});throw cleanupError}sessionDiag(attempt,{stage:"consume_final",network:CURRENT_NETWORK,provider:handoff?.source,ok:false,reason:"handoff-failed",errorClass:sessionDiagErrorClass(error)});return false}}
async function restoreAppSession(){const attempt=sessionDiagAttempt(CURRENT_NETWORK);let record,raw=null;try{raw=sessionStorage.getItem(APP_SESSION_KEY);sessionDiag(attempt,{stage:"restore_load",network:CURRENT_NETWORK,ok:true,reason:raw?"loaded":"not-found"});try{record=JSON.parse(raw||"null");sessionDiag(attempt,{stage:"restore_parse",network:CURRENT_NETWORK,ok:true,reason:"parsed"})}catch(error){sessionDiag(attempt,{stage:"restore_parse",network:CURRENT_NETWORK,ok:false,reason:"malformed",errorClass:sessionDiagErrorClass(error)});removeAppSession();return false}}catch(error){sessionDiag(attempt,{stage:"restore_load",network:CURRENT_NETWORK,ok:false,reason:"storage-read-failed",errorClass:sessionDiagErrorClass(error)});removeAppSession();return false}if(!record)return false;const valid=validWalletSession(record);sessionDiag(attempt,{stage:"restore_validation",network:CURRENT_NETWORK,provider:record?.source,ok:valid,reason:valid?"valid":"invalid"});if(!valid){removeAppSession();return false}try{const p=await waitForWalletProvider(record.source,4000,attempt),current=await connectTrustedWallet(p,record.wallet,attempt);if(!current||current!==record.wallet||p.isConnected===false)throw new Error("trusted_wallet_mismatch");walletAddress=record.wallet;walletSource=record.source;activeProvider=p;protectionToken=record.token;verifiedGenesisHash=record.genesisHash;bindWalletEvents(p);rememberWallet(walletAddress,walletSource);document.querySelector("main").classList.remove("product-pending");sessionDiag(attempt,{stage:"restore_final",network:CURRENT_NETWORK,provider:record.source,ok:true,reason:"session-saved"});return true}catch(error){sessionDiag(attempt,{stage:"restore_final",network:CURRENT_NETWORK,provider:record?.source,ok:false,reason:"restore-failed",errorClass:sessionDiagErrorClass(error)});removeAppSession();return false}}
